using System;
using System.Linq;
using System.Collections.Generic;
using System.Globalization;
namespace PeerChatDesktop {
// Copies only existing archive presentation/accounting. No native command or scheduler is owned here.
public sealed class HistoryDiagnosticInput {
    public string Scope="",Device="",Source="",State="",Activity="Unavailable",Native="",ResultSource="",Unavailable="";public long Account,Scan,Processed,Imported,Conversations,Attachments,Unresolved,RejectedBatches,HistoryRevision,LastSuccessful,ResultAt,ResultImported,ResultConversations,ResultUnresolved,ProvidedQueued;
    public int Result;public bool Current,Running,Complete,Enabled;public bool? Automatic;public string[] Providers=new string[0];
}
public sealed class DiagnosticObservedEntry {
    public string Id,Description,Details,Subsystem,Severity;public DateTime? Utc;
    public string Summary {get{return ConnectionPreviewDisplay.Compact(Description)+"\n"+(Utc.HasValue?ConnectionPreviewDisplay.Local(Utc.Value):"Timestamp: Not retained")+" · "+Severity+" · "+Subsystem;}}
    public string UtcTimestamp {get{return Utc.HasValue?ConnectionPreviewDisplay.Utc(Utc.Value):"Not retained";}}
}
public sealed class HistoryDiagnosticHistory {
    readonly Queue<DiagnosticObservedEntry> events=new Queue<DiagnosticObservedEntry>();string owner="",signature="";
    public DiagnosticObservedEntry[] Events {get{return events.ToArray();}}
    public void Clear(){events.Clear();owner=signature="";}
    public void Observe(HistoryDiagnosticInput input,DateTime utc){
        if(input==null)return;if(owner!=input.Scope){Clear();owner=input.Scope;}if(!input.Current)return;
        string next=input.Scan+":"+input.Source+":"+input.Activity+":"+input.State+":"+input.Imported+":"+input.Conversations+":"+input.Unresolved+":"+input.Result+":"+input.ResultAt+":"+input.ProvidedQueued+":"+String.Join(",",input.Providers??new string[0]);
        if(next==signature)return;signature=next;events.Enqueue(new DiagnosticObservedEntry{Id=input.Scope+"/scan:"+input.Scan+"/observed:"+utc.Ticks,Utc=utc,Subsystem="History Sync",Severity=input.Activity=="Failed"?"Error":input.Unresolved>0?"Warning":"Info",Description="Observed "+input.Activity+" · "+input.Imported+" verified imports · "+input.Conversations+" conversations · "+input.ProvidedQueued+" source records queued (includes retries)",Details="Observer UTC: "+ConnectionPreviewDisplay.Utc(utc)+" (not a reconstructed start/completion timestamp)\nContext: "+input.Scope+"\nScan: "+input.Scan+"\nReader: "+input.Device+"\nSource: "+input.Source+"\nState: "+ConnectionsSafeText.Clean(input.State)+"\nUnresolved: "+input.Unresolved+"\nCompleted result: "+HistoryDiagnosticProjection.Outcome(input.Result)+" / "+HistoryDiagnosticProjection.Time(input.ResultAt)});while(events.Count>64)events.Dequeue();
    }
}
public static class HistoryDiagnosticProjection {
    public static string Outcome(int result){return result>=1&&result<=4?new[]{"None","Full","Partial","Failed","Cancelled"}[result]:"Not retained — no completed result";}
    public static string Time(long ms){try{return ms>0?ConnectionPreviewDisplay.Local(new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc).AddMilliseconds(ms))+"\nUTC: "+new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc).AddMilliseconds(ms).ToString("o",CultureInfo.InvariantCulture):"Not retained";}catch{return "Unavailable — invalid retained timestamp";}}
    public static DiagnosticPanel Card(string title,params string[] fields){return new DiagnosticPanel{Title=title,Metrics=Enumerable.Range(0,fields.Length/2).Select(i=>new DiagnosticMetric(fields[i*2],ConnectionsSafeText.Clean(fields[i*2+1]))).ToArray()};}
    static string Count(HistoryDiagnosticInput p,long n){return p.Current?n.ToString(CultureInfo.InvariantCulture):"Unavailable — current authenticated cache required";}
    static string Lines(string text,params string[] prefixes){return String.Join("\n",(text??"").Split('\n').Where(line=>prefixes.Any(prefix=>line.StartsWith(prefix,StringComparison.Ordinal))).Take(128).Select(ConnectionsSafeText.Clean));}
    public static DiagnosticUiSnapshot Read(HistoryDiagnosticInput p,HistoryDiagnosticHistory history){
        p=p??new HistoryDiagnosticInput();string absent=p.Unavailable.Length>0?ConnectionsSafeText.Clean(p.Unavailable):"No current authenticated archive cache";string source=p.Current&&p.Running&&p.Source.Length>0?p.Source:"No active reader source";string role=!p.Current?"Unavailable":p.Providers.Length>0?p.Running?"Reader and source (independent scopes)":"Source providing to readers":p.Running?"Reader":"Idle — no active source/reader work";
        var pages=new[]{new DiagnosticPage{Tab="Overview",Panels=new[]{Card("Current synchronization activity","State",p.Current?p.Activity:absent,"Native detail",p.Current?p.State:"Unavailable","Role / direction",role,"Local device (reader when importing)",p.Current?p.Device:"Unavailable","Reader's source",source,"Providing to readers",p.Current?String.Join("\n",p.Providers):"Unavailable","Conversations processed",Count(p,p.Conversations),"Verified messages imported",Count(p,p.Imported),"Source records queued (includes retries)",Count(p,p.ProvidedQueued),"Unresolved records",Count(p,p.Unresolved)),Card("Last completed result — separate from current activity","Outcome",p.Current?Outcome(p.Result):"Unavailable — not borrowed from another account","Completed time",p.Current?Time(p.ResultAt):"Unavailable","Completed reader source",p.Current?p.ResultSource:"Unavailable","Verified imports in that result",p.Current&&p.Result>0?Count(p,p.ResultImported):"Not retained","Completed conversations",p.Current&&p.Result>0?Count(p,p.ResultConversations):"Not retained","Unresolved at completion",p.Current&&p.Result>0?Count(p,p.ResultUnresolved):"Not retained","Last successful completion",p.Current?Time(p.LastSuccessful):"Unavailable"),Card("Existing scheduler and policy","History Sync",p.Current?p.Enabled?"ON":"OFF":"Unavailable","Local automatic synchronization",p.Current&&p.Automatic.HasValue?p.Automatic.Value?"ON":"OFF":"Unavailable — preference not in current cache","Scan generation",Count(p,p.Scan),"Collector behavior","Read-only application cache. Opening diagnostics does not start scans, refresh metadata, grant permission or change scheduler cadence.")}},
        new DiagnosticPage{Tab="Connections",Panels=new[]{Card("Authenticated source / reader relationship","Account",p.Current?p.Account.ToString():"Unavailable","Device",p.Current?p.Device:"Unavailable","Source",source,"Admission / signed grant evidence",p.Current?Lines(p.Native,"scope=","authorizer=","grant ","source=","source_eligibility=","active_scope","intent_"):absent),Card("Archive route and recovery","Current route evidence",p.Current?Lines(p.Native,"archive_route","archive_transport","last_incoming_archive=","data_rejection_stage=","last_source_rejection_stage=","state="):absent,"Transport boundaries","Archive scope only — not the selected DM, file or WebRTC route. A winner/connection is not proof of imported records.","TLS / authentication","Only existing archive_transport stages and exact-scope checks shown; cryptographic transport detail not independently instrumented here.")}},
        new DiagnosticPage{Tab="Records",Panels=new[]{Card("Reader accounting — not source submission","Records processed (may include existing records)",Count(p,p.Processed),"Verified new durable imports",Count(p,p.Imported),"Completed conversations",Count(p,p.Conversations),"Attachment records (not file downloads)",Count(p,p.Attachments),"Unresolved provenance / deferred",Count(p,p.Unresolved),"Rejected batches",Count(p,p.RejectedBatches),"History revision",Count(p,p.HistoryRevision)),Card("Source accounting and commit boundaries","Source records queued including retries",Count(p,p.ProvidedQueued),"Successfully transmitted / reader ACK count","N/A — not exported separately","Eligible record total","N/A — no reliable total exported","Deduplicated record count","N/A — not exported; processed minus imports is not a deduplication measurement","Per-conversation cursor values","Not exposed — no cursor database is read or changed by diagnostics","Per-conversation progress","Completed count only; individual current conversation identity/progress not exported","Scan/page/attempt state",p.Current?Lines(p.Native,"messages_processed=","imports_committed=","current_activity="):absent,"Commit semantics","Imported counters come from verified native durable import callbacks; cursor/ACK security remains native-owned.")}},
        new DiagnosticPage{Tab="Events",Panels=new[]{Card("Observed synchronization lifecycle","Boundary","Only observations since this diagnostic view opened, plus existing bounded native attempt evidence. No reconstructed history.","Observed entries",history==null?"0":history.Events.Length.ToString(),"Timeline",history==null?"Not retained":String.Join("\n\n",history.Events.Select(e=>e.Summary+"\n"+e.Details)),"Existing native attempt evidence (timestamps not retained)",p.Current?Lines(p.Native,"archive_transport","last_incoming_archive=","data_rejection_stage=","last_source_rejection_stage="):absent)}}};
        return new DiagnosticUiSnapshot{Context=new DiagnosticContext(DiagnosticSection.HistorySync,p.Scope),Sample=false,Banner="LIVE HISTORY DIAGNOSTICS · existing authenticated application cache · current activity ≠ last completed result",Pages=pages};
    }
    public static string Export(DiagnosticUiSnapshot snapshot){return "PeerChat diagnostics · "+(snapshot.Sample?"SAMPLE FIXTURE — NOT PHYSICAL ACCEPTANCE":"REAL diagnostic snapshot")+"\nBuild: "+PeerChat.VersionInfo.Display+"\nObserved UTC: "+DateTime.UtcNow.ToString("o")+"\nContext: "+ConnectionsSafeText.Clean(snapshot.Context.StableId)+"\n"+String.Join("\n\n",snapshot.Pages.Select(page=>page.Tab+"\n"+String.Join("\n\n",page.Panels.Select(panel=>panel.Title+"\n"+String.Join("\n",panel.Metrics.Select(metric=>metric.Label+": "+metric.Value))))));}
}
}
